import csv, os, math
base = "/workspace/artifact/ICSE2024-funcConstructs-Artifacts/results"
def read_lambda(p):
    rows = []
    with open(p) as f:
        reader = csv.DictReader(f)
        for r in reader:
            rows.append({k: float(v) for k, v in r.items()})
    return rows
def read_mrf(p):
    with open(p) as f:
        lines = [line.strip() for line in f.readlines()]
    return [{'OR': float(lines[1]), 'Value': float(lines[2]), 'Std. Error': float(lines[3]), 't value': float(lines[4]), 'p value': float(lines[5])}]
lambda_rows = read_lambda(os.path.join(base, "Table-9-rq2-lambda.csv"))
comp_rows = read_lambda(os.path.join(base, "Table-9-rq2-comp.csv"))
mrf_rows = read_mrf(os.path.join(base, "Table-9-rq2-mrf.csv"))
expected = {
    'lambda': [
        {'OR': 2.29, 'Value': 0.83, 'Std. Error': 0.31, 't value': 2.65, 'p value': 0.02},
        {'OR': 0.88, 'Value': -0.13, 'Std. Error': 0.18, 't value': -0.73, 'p value': 0.47}
    ],
    'comp': [
        {'OR': 1.49, 'Value': 0.40, 'Std. Error': 0.22, 't value': 1.84, 'p value': 0.07},
        {'OR': 0.77, 'Value': -0.26, 'Std. Error': 0.11, 't value': -2.27, 'p value': 0.05}
    ],
    'mrf': [
        {'OR': 1.79, 'Value': 0.58, 'Std. Error': 0.25, 't value': 2.31, 'p value': 0.02}
    ]
}
tol = 0.005  # rounding error tolerance
for (name, rows, exp_rows) in [('lambda', lambda_rows, expected['lambda']), ('comp', comp_rows, expected['comp']), ('mrf', mrf_rows, expected['mrf'])]:
    for i, (row, exp) in enumerate(zip(rows, exp_rows)):
        for key in ['OR', 'Value', 'Std. Error', 't value', 'p value']:
            diff = abs(row[key] - exp[key])
            if diff > tol:
                print(f"FAIL: {name} row {i} {key}: got {row[key]}, expected {exp[key]}, diff {diff}")
                exit(1)
print("SUCCESS: All values match within rounding tolerance")
EOF

